def int_to_binary(n: int) -> str:
    if n < 0 or n > 1024:
        raise ValueError("Input must be between 0 and 1024")
    # Convert the integer to binary using built-in bin() function
    binary_str = bin(n)[2:]  # Remove the '0b' prefix
    # Ensure there are no leading zeros by slicing from the first non-zero character
    return binary_str.lstrip('0')
