from typing import List

def merge_intervals(iv: List[tuple[int, int]]) -> List[tuple[int, int]]:
    if not iv:
        return []

    merged = [iv[0]]
    for interval in iv[1:]:
        if interval[0] <= merged[-1][1]:
            # Ensure that the last element of merged is updated correctly
            merged[-1] = (min(merged[-1][0], interval[0]), max(merged[-1][1], interval[1]))
        else:
            merged.append(interval)

    return merged
```

Explanation:
The solution now correctly handles the case where the last element of the `merged` list needs to be updated after an overlap. This ensures that the final output meets the required conditions.

